function getCCTPDomain(chain) {
  switch (chain) {
    case "ethereum":
      return 0;
    case "avalanche":
      return 1;
    case "optimism":
      return 2;
    case "arbitrum":
      return 3;
    case "solana":
      return 5;
    case "base":
      return 6;
    case "polygon":
      return 7;
    case "sui":
      return 8;
    case "unichain":
      return 10;
    case "linea":
      return 11;
    case "sonic":
      return 13;
    default:
      throw new Error("unsupported chain for cctp");
  }
}
